24	@SpringBootTest
25	@AutoConfigureMockMvc
26	class EvidenceApiTest {
27	
28	    private static final String ACTOR_HEADER = "X-Actor-Id";
29	
30	    @Autowired
31	    private MockMvc mockMvc;
32	
33	    @Autowired
34	    private ObjectMapper objectMapper;
35	
36	    private String uniqueKey(String prefix) {
37	        return prefix + "-" + UUID.randomUUID().toString().substring(0, 12);
38	    }
39	
40	    private Map<String, Object> intakeBody(String commandKey, String evidenceKey) {
41	        Map<String, Object> body = new LinkedHashMap<>();
42	        body.put("commandKey", commandKey);
43	        body.put("evidenceKey", evidenceKey);
44	        body.put("caseKey", "CASE-1");
45	        body.put("category", "DOCUMENT");
