58	    private MvcResult initiate(String actor, String evidenceKey, String commandKey,
59	                               String toCustodian) throws Exception {
60	        Map<String, Object> body = new LinkedHashMap<>();
61	        body.put("commandKey", commandKey);
62	        body.put("toCustodian", toCustodian);
63	        return mockMvc.perform(post("/api/evidence/{key}/transfers", evidenceKey)
64	                        .header(ACTOR_HEADER, actor)
