                    .orElseThrow(() -> ApiException.notFound("证物不存在: " + key));
            requireCustodian(evidence, actorId);
        }
        Optional<StoredResponse> replay = checkReplay(request.requestId(), requestHash);
        if (replay.isPresent()) {
