        }
        // 串行边界：批次登记与污染传播在同一事件序列行锁内执行，扩散后不会插入漏管批次
        long eventSeq = contactBatchRepository.nextEventSeq();
        LocalDateTime nowUtc = clock.nowUtc();
        for (String key : members) {
            Evidence locked = evidenceRepository.findByKeyForUpdate(key).orElseThrow();
            requireCustodian(locked, actorId);
            if (locked.status() != EvidenceStatus.SEALED) {
                throw ApiException.conflict("成员证物状态不允许参加接触批次: " + key + " (" + locked.status() + ")");
