    @Transactional
    public StoredResponse registerContamination(String actorId, ContaminationCreateRequest request, String requestHash) {
        // 权限先于重放：仅起点证物当前保管人可登记
        Evidence origin = evidenceRepository.findByKey(request.evidenceKey())
                .orElseThrow(() -> ApiException.notFound("证物不存在: " + request.evidenceKey()));
        requireCustodian(origin, actorId);
        Optional<StoredResponse> replay = checkReplay(request.requestId(), requestHash);
        if (replay.isPresent()) {
            return replay.get();
        }
        // 串行边界：与批次登记共用事件序列行锁
        contactBatchRepository.lockSequence();
        Evidence lockedOrigin = evidenceRepository.findByKeyForUpdate(request.evidenceKey()).orElseThrow();
        requireCustodian(lockedOrigin, actorId);
        if (!contactBatchRepository.existsBySeq(request.startSeq())) {
            throw ApiException.notFound("接触事件序号不存在: " + request.startSeq());
        }
        // 从起点序号（含）起按序号递增传播；之前批次不追溯
        LinkedHashMap<String, String> affected = new LinkedHashMap<>(); // evidenceKey -> sourceBatchKey(null=起点)
        affected.put(request.evidenceKey(), null);
        for (ContactBatch batch : contactBatchRepository.findBatchesFromSeq(request.startSeq())) {
            List<String> members = contactBatchRepository.findMembers(batch.batchKey());
            boolean hit = members.stream().anyMatch(affected::containsKey);
            if (hit) {
                for (String member : members) {
                    affected.putIfAbsent(member, batch.batchKey());
                }
            }
        }
        LocalDateTime nowUtc = clock.nowUtc();
        // 整次原子标记：SEAL_BROKEN 为既有终态，保留不覆盖；其余状态一律置为 CONTAMINATED
        for (String key : affected.keySet()) {
            evidenceRepository.markContaminated(key, nowUtc);
        }
        contaminationRepository.insert(request.requestId(), request.evidenceKey(), request.startSeq(),
                actorId, affected.size(), nowUtc);
        for (Map.Entry<String, String> entry : affected.entrySet()) {
            contaminationRepository.insertAffected(request.requestId(), entry.getKey(), entry.getValue(), nowUtc);
        }
        ContaminationView view = toView(...);
        return record(request.requestId(), OP_CONTAMINATION, actorId, requestHash, 201, view);
    }
