/**
 * 接触批次与污染传播 API 主流程、失败分支与幂等测试。
 * 合成场景：A 接 B（第一批），B 接 C（第二批）；
 * 从 A 在第一批污染隔离 A、B、C，从 B 在第二批污染只隔离 B、C。
 */
@SpringBootTest
@AutoConfigureMockMvc
